function example() {
  const [value, setValue] = useState(500);
  return (
    <Block>
      <Slider
        value={value}
        onChange={setValue}
        min={0}
        max={1000}
        step={50}
        showOutput
        color="primary"
      />
      <Paragraph mt="4">Value: ${value}</Paragraph>
    </Block>
  );
}

function example() {
  const [range, setRange] = useState<[number, number]>([200, 800]);
  return (
    <Block>
      <Slider
        range
        label="Price range"
        value={range}
        onChange={setRange}
        min={0}
        max={1000}
        step={50}
        color="primary"
      />
      <Paragraph mt="4">
        ${range[0]} to ${range[1]}
      </Paragraph>
    </Block>
  );
}

function example() {
  const [value, setValue] = useState(50);
  return (
    <Block>
      <Slider
        value={value}
        onChange={setValue}
        showOutput
        color="success"
        formatOutput={v => `${v}%`}
      />
      <Paragraph mt="4">Progress: {value}%</Paragraph>
    </Block>
  );
}

function example() {
  return (
    <Field horizontal label="Volume" labelProps={{ htmlFor: 'volume-field' }}>
      <Field.Body>
        <Field>
          <Slider id="volume-field" defaultValue={50} color="primary" />
        </Field>
      </Field.Body>
    </Field>
  );
}

function example() {
  return (
    <Field
      horizontal
      label="Volume"
      labelProps={{ htmlFor: 'volume-field-control' }}
    >
      <Field.Body>
        <Field>
          <Control iconLeftName="volume-up">
            <Slider
              id="volume-field-control"
              defaultValue={50}
              color="primary"
            />
          </Control>
        </Field>
      </Field.Body>
    </Field>
  );
}
